import{_ as a,o as e,a as r,b as c}from"./app.BGziXukh.js";const o="/ascendc.github.io/assets/address_overlap_unsupported.XPeiarSp.png",p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"通用说明和约束","link":"/api/SIMD-API/general_description_and_constraints"}]},"headers":[],"relativePath":"api/SIMD-API/general_description_and_constraints.md","filePath":"api/SIMD-API/general_description_and_constraints.md","outlineHeaders":[{"level":2,"title":"通用约束","slug":"通用约束","link":"#通用约束"},{"level":3,"title":"通用地址对齐约束","slug":"通用地址对齐约束","link":"#通用地址对齐约束"},{"level":3,"title":"通用地址重叠约束","slug":"通用地址重叠约束","link":"#通用地址重叠约束"},{"level":3,"title":"原子操作","slug":"原子操作","link":"#原子操作"},{"level":3,"title":"数据依赖与同步","slug":"数据依赖与同步","link":"#数据依赖与同步"},{"level":2,"title":"通用说明","slug":"通用说明","link":"#通用说明"},{"level":3,"title":"所需头文件和库文件","slug":"所需头文件和库文件","link":"#所需头文件和库文件"},{"level":3,"title":"数据存储位置的描述方式","slug":"数据存储位置的描述方式","link":"#数据存储位置的描述方式"},{"level":4,"title":"C API：地址空间限定符","slug":"C-API：地址空间限定符","link":"#C-API：地址空间限定符"},{"level":4,"title":"Tensor API：location","slug":"Tensor-API：location","link":"#Tensor-API：location"},{"level":4,"title":"基础API和高阶API：TPosition","slug":"基础API和高阶API：TPosition","link":"#基础API和高阶API：TPosition"}],"lastUpdated":1794554078000}'),i={name:"api/SIMD-API/general_description_and_constraints.md"};function d(_,t,s,l,n,h){return e(),r("div",null,[...t[0]||(t[0]=[c('<div><article class="markdown-body"><h1>通用说明和约束<a id="simd_api_general_description_constraints"></a></h1><p>本文面向SIMD API开发者，介绍<a href="c_api/c_api.html">C API</a>、<a href="tensor_api/tensor_api.html">Tensor API</a>、<a href="basic_api/basic_api.html">基础API</a>和<a href="adv_api/adv_api.html">高阶API</a>四类API在使用过程中需要关注的通用说明和约束。</p><p><strong>表1</strong> 各类API的基本编程方式和参考资料</p><table><thead><tr><th>API类型</th><th>编程方式</th><th>参考文档</th></tr></thead><tbody><tr><td>C API</td><td>基于C语言指针编程，由开发者管理本地内存和同步。</td><td><a href="../../guide/programming_guide/programming_model/ai_core_simd_programming/c_pointer_programming/c_programming_overview.html">C语言编程概述</a></td></tr><tr><td>Tensor API</td><td>基于携带Layout信息的扩展Tensor编程。</td><td><a href="../../guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/cpp_tensor_programming_overview.html">C++ Tensor编程概述</a></td></tr><tr><td>基础API</td><td>基于C++基础Tensor编程，可由开发者管理本地内存和同步，也可结合TPipe和TQue管理资源与流水同步。</td><td><a href="../../guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/cpp_tensor_programming_overview.html">C++ Tensor编程概述</a><br><a href="../../guide/programming_guide/programming_model/ai_core_simd_programming/tpipe_tque_programming/tpipe_tque_paradigm.html">TPipe和TQue编程范式</a></td></tr><tr><td>高阶API</td><td>基于C++ Tensor编程，通常结合TPipe和TQue编程范式使用。</td><td><a href="../../guide/programming_guide/programming_model/ai_core_simd_programming/tpipe_tque_programming/tpipe_tque_paradigm.html">TPipe和TQue编程范式</a></td></tr></tbody></table><h2 id="通用约束">通用约束<a class="header-anchor" href="#通用约束">​</a></h2><h3 id="通用地址对齐约束">通用地址对齐约束<a id="alignment_requirements"></a><a class="header-anchor" href="#通用地址对齐约束">​</a></h3><p>AI Core上的存储单元用于存储矢量计算、矩阵计算的源操作数和目的操作数，各类存储单元的对齐要求如<a href="#alignment_requirements_table">表2</a>所示，因此Ascend C API操作数的起始地址对齐要求应与这些存储单元的对齐要求保持一致。<strong>需要注意的是，如果接口中已明确说明操作数起始地址对齐要求，则以具体API中的说明为准。</strong></p><p><strong>表2</strong> 不同存储单元的常见对齐要求</p><p><a id="alignment_requirements_table"></a></p><table><thead><tr><th>存储位置</th><th>常见对齐要求</th></tr></thead><tbody><tr><td>Global Memory</td><td>无对齐要求</td></tr><tr><td>UB</td><td>32Byte对齐</td></tr><tr><td>L1 Buffer</td><td>32Byte对齐</td></tr><tr><td>L0A Buffer/L0B Buffer</td><td>512Byte对齐</td></tr><tr><td>L0C Buffer</td><td>64Byte对齐</td></tr><tr><td>BiasTable Buffer</td><td>64Byte对齐</td></tr><tr><td>Fixpipe Buffer</td><td>64Byte对齐</td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 上表所述地址对齐要求适用于一般情况，具体接口可能有不同要求。下面列举部分特殊情况（涉及的接口以C API为例）：</p><ul><li>Global Memory：<a href="c_api/vector_datamove/asc_ndim_copy_gm2ub.html">asc_ndim_copy_gm2ub</a>的数据类型为b16、b32时，GM源地址分别要求2Byte、4Byte对齐。</li><li>UB：<a href="c_api/vector_datamove/asc_ndim_copy_gm2ub.html">asc_ndim_copy_gm2ub</a>的UB目的地址仅要求1Byte对齐。</li><li>L0C Buffer：NPU架构版本3510的<a href="c_api/cube_compute/mmad_compute/asc_mmad.html">asc_mmad</a>要求L0C结果地址1024Byte对齐。</li><li>Fixpipe Buffer：NPU架构版本3510的<a href="c_api/cube_datamove/cube_compute_load/asc_copy_l12fb_arch_3510.html">asc_copy_l12fb</a>要求随路Vector量化参数地址128Byte对齐。</li></ul></div><h3 id="通用地址重叠约束">通用地址重叠约束<a id="address_overlap_constraints"></a><a class="header-anchor" href="#通用地址重叠约束">​</a></h3><p>使用高维切分计算接口时，为了节省地址空间，可以使源操作数和目的操作数使用同一段存储空间。使用地址重叠时，需要满足以下约束：</p><ul><li>单次迭代内，源操作数与目的操作数必须完全重叠，不支持部分重叠。</li><li>多次迭代间，不支持前序迭代的目的操作数与后序迭代的源操作数重叠。例如，第N次迭代的目的操作数是第N+1次迭代的源操作数时，第N次迭代可能改写后续迭代仍需读取的源数据，导致计算结果不符合预期。</li><li>对于部分双目计算类接口，当数据类型为half、int32_t或float时，可在满足接口特定条件的情况下支持前序迭代的目的操作数与后序迭代的源操作数重叠。该重叠仅限于目的操作数与第二个源操作数重叠，且<code>src1RepStride</code>或<code>dstRepStride</code>必须为0；具体支持的接口以对应API文档为准。</li><li>多次迭代间，不支持前序迭代的目的操作数与后序迭代的目的操作数重叠。前序迭代写入的数据可能被后续迭代覆盖，导致计算结果不符合预期。</li></ul><p><strong>图1</strong> 地址重叠示例（不支持）<a id="address_overlap_example"></a><br><img src="'+o+'" alt title="地址重叠示例（不支持）"></p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本节所述地址重叠通用约束适用于C API和基础API的一般情况，API参考中如有额外特殊说明的，则以具体API中的说明为准。 API中没有描述地址重叠约束的，视为不支持Tensor高维切分计算的地址重叠，地址重叠时计算结果可能不满足预期。</p></div><h3 id="原子操作">原子操作<a class="header-anchor" href="#原子操作">​</a></h3><p>原子操作用于多个执行单元或多个核并发访问同一Global Memory位置的场景。普通写入可能发生读改写覆盖：多个执行单元先后读取相同旧值，再分别写回结果，后写入的结果会覆盖先写入的结果。原子操作把指定位置的读-修改-写过程作为一个不可分割的操作，避免并发更新相互覆盖。</p><p>原子操作包括以下两种类型：</p><ul><li>数据搬运随路原子操作：作用于后续写入Global Memory的数据搬运。</li><li>Scalar原子操作：直接对指定Global Memory地址执行加、减、最大值、最小值、交换或比较交换。</li></ul><p>四类API在涉及并发更新Global Memory数据时，可使用的原子操作接口及其描述如下表3所示。</p><p><strong>表3</strong> 原子操作接口和使用方式</p><table><thead><tr><th>API类别</th><th>原子操作接口和使用方式</th></tr></thead><tbody><tr><td>C API</td><td><br>• 数据搬运随路原子操作：<br><a href="c_api/atomic/datamove_atomic/asc_set_atomic_add.html">asc_set_atomic_add</a>、<a href="c_api/atomic/datamove_atomic/asc_set_atomic_max.html">asc_set_atomic_max</a>、<a href="c_api/atomic/datamove_atomic/asc_set_atomic_min.html">asc_set_atomic_min</a>、<a href="c_api/atomic/datamove_atomic/asc_disable_dma_atomic.html">asc_disable_dma_atomic</a><br>• Scalar原子操作：<br><a href="c_api/atomic/scalar_atomic/asc_atomic_add.html">asc_atomic_add</a>、<a href="c_api/atomic/scalar_atomic/asc_atomic_min.html">asc_atomic_min</a>、<a href="c_api/atomic/scalar_atomic/asc_atomic_max.html">asc_atomic_max</a>、<a href="c_api/atomic/scalar_atomic/asc_atomic_exch.html">asc_atomic_exch</a>、<a href="c_api/atomic/scalar_atomic/asc_atomic_cas.html">asc_atomic_cas</a></td></tr><tr><td>Tensor API</td><td>Tensor API的同步控制、原子操作等底层控制能力由C API提供。需要原子更新时，使用对应的C API原子接口，并同时满足Tensor API的Layout、访问范围和同步要求。</td></tr><tr><td>基础API</td><td><br>• 数据搬运随路原子操作：<br><a href="basic_api/atomic_operations/SetAtomicAdd.html">SetAtomicAdd</a>、<a href="basic_api/atomic_operations/SetAtomicMax_ISASI.html">SetAtomicMax</a>、<a href="basic_api/atomic_operations/SetAtomicMin_ISASI.html">SetAtomicMin</a>、<a href="basic_api/atomic_operations/DisableDmaAtomic.html">DisableDmaAtomic</a><br>• Scalar原子操作：<br><a href="basic_api/atomic_operations/AtomicAdd.html">AtomicAdd</a>、<a href="basic_api/atomic_operations/AtomicMin.html">AtomicMin</a>、<a href="basic_api/atomic_operations/AtomicMax.html">AtomicMax</a>、<a href="basic_api/atomic_operations/AtomicExch.html">AtomicExch</a>、<a href="basic_api/atomic_operations/AtomicCas.html">AtomicCas</a></td></tr><tr><td>高阶API</td><td>Matmul接口可通过<a href="adv_api/cube_compute/Matmul_Kernel/GetTensorC.html">GetTensorC</a>的<code>enAtomic</code>参数开启AtomicAdd、AtomicMax或AtomicMin操作。其他高阶API是否支持原子操作以具体接口说明为准；接口未提供相关能力时，可使用基础API的原子操作接口。</td></tr></tbody></table><p>使用原子累加时，初始值写入和后续原子更新必须建立明确的执行顺序，避免普通写入覆盖尚未完成的原子更新。原子操作保证单次更新的不可分割性，不保证多个原子更新按源码顺序完成；浮点累加还可能因执行顺序不同而产生数值差异。需要确定执行顺序时，仍需使用适用的核内或核间同步接口。</p><p>确定性计算的具体要求请参考基础API的<a href="basic_api/atomic_operations/key_features.html">原子操作特性说明</a>和C API的<a href="c_api/atomic/key_features.html">原子操作特性说明</a>。</p><h3 id="数据依赖与同步">数据依赖与同步<a class="header-anchor" href="#数据依赖与同步">​</a></h3><p>AI Core中的数据搬运、矢量计算和矩阵计算由不同的硬件流水线执行，同一核内的各流水线以及不同核之间的指令都可能异步执行。例如，从GM搬入UB的数据通常由MTE2流水线写入，后续矢量计算由Vector流水线读取；不同核之间也可能通过Global Memory或片上存储交换数据。即使相关接口在源码中按先后顺序调用，后续操作也可能在前序数据写入完成前开始执行。因此，存在两类同步：</p><ul><li>同一AI Core内不同流水线之间存在数据依赖时，需要通过核内同步建立执行先后关系；</li><li>不同核之间存在数据依赖时，需要通过核间同步建立执行先后关系。</li></ul><p>四类API在核内流水依赖场景下可使用的同步接口如下：</p><p><strong>表4</strong> 核内同步接口</p><table><thead><tr><th>API类别</th><th>不同流水线之间的同步</th><th>同一流水线内的同步</th></tr></thead><tbody><tr><td>C API</td><td>流水事件同步：<br>• <a href="c_api/sync/intra_core_sync/asc_sync_notify.html">asc_sync_notify</a>/<a href="c_api/sync/intra_core_sync/asc_sync_wait.html">asc_sync_wait</a><br>• Ascend 950PR&amp;950DT系列产品还可使用<a href="c_api/sync/intra_core_sync/asc_lock.html">asc_lock</a>/<a href="c_api/sync/intra_core_sync/asc_unlock.html">asc_unlock</a></td><td>使用<a href="c_api/sync/intra_core_sync/asc_sync_pipe.html">asc_sync_pipe</a>等待指定流水线的前序指令完成。</td></tr><tr><td>Tensor API</td><td>配合C API处理流水间依赖：<br>• <a href="c_api/sync/intra_core_sync/asc_sync_notify.html">asc_sync_notify</a>/<a href="c_api/sync/intra_core_sync/asc_sync_wait.html">asc_sync_wait</a><br>• <a href="c_api/sync/intra_core_sync/asc_lock.html">asc_lock</a>/<a href="c_api/sync/intra_core_sync/asc_unlock.html">asc_unlock</a></td><td>配合C API的<a href="c_api/sync/intra_core_sync/asc_sync_pipe.html">asc_sync_pipe</a>处理单流水依赖。</td></tr><tr><td>基础API</td><td>流水事件同步：<br>• <a href="basic_api/sync_control/intra_core_sync/SetFlag_WaitFlag_ISASI.html">SetFlag/WaitFlag</a><br>• <a href="basic_api/sync_control/intra_core_sync/TQueSync.html">TQueSync</a>类的同名成员函数<br>• Ascend 950PR&amp;950DT系列产品还可使用<a href="basic_api/sync_control/intra_core_sync/Mutex_ISASI.html">Mutex</a>的<a href="basic_api/sync_control/intra_core_sync/Lock.html">Lock</a>/<a href="basic_api/sync_control/intra_core_sync/Unlock.html">Unlock</a></td><td>使用<a href="basic_api/sync_control/intra_core_sync/PipeBarrier_ISASI.html">PipeBarrier</a>等待指定流水线的前序指令完成。</td></tr><tr><td>高阶API</td><td>高阶API的部分接口会提供明确的同步模式或配套等待接口：<br>• Matmul接口通过<code>sync</code>参数区分同步、异步模式，异步模式需要调用配套的等待接口。<br>• <a href="adv_api/tensor_transform/Fill.html">Fill</a>文档明确要求调用者在特定流水依赖场景下插入同步。</td><td>使用<a href="basic_api/sync_control/intra_core_sync/PipeBarrier_ISASI.html">PipeBarrier</a>等待指定流水线的前序指令完成。</td></tr></tbody></table><p>不同AI Core之间存在执行顺序要求时，需要使用核间同步接口。四类API的核间同步接口如下：</p><p><strong>表5</strong> 核间同步接口</p><table><thead><tr><th>API类别</th><th>核间同步接口</th></tr></thead><tbody><tr><td>C API</td><td>使用四类核间同步接口：<br>• <a href="c_api/sync/inter_core_sync/asc_sync_block_arrive.html">asc_sync_block_arrive</a>/<a href="c_api/sync/inter_core_sync/asc_sync_block_wait.html">asc_sync_block_wait</a><br>• <a href="c_api/sync/inter_core_sync/asc_sync_inter_arrive.html">asc_sync_inter_arrive</a>/<a href="c_api/sync/inter_core_sync/asc_sync_inter_wait.html">asc_sync_inter_wait</a><br>• <a href="c_api/sync/inter_core_sync/asc_sync_intra_arrive.html">asc_sync_intra_arrive</a>/<a href="c_api/sync/inter_core_sync/asc_sync_intra_wait.html">asc_sync_intra_wait</a><br>• <a href="c_api/sync/inter_core_sync/asc_sync_subblock_arrive.html">asc_sync_subblock_arrive</a>/<a href="c_api/sync/inter_core_sync/asc_sync_subblock_wait.html">asc_sync_subblock_wait</a></td></tr><tr><td>Tensor API</td><td>Tensor API的核间同步能力由C API提供。</td></tr><tr><td>基础API</td><td>硬件同步：<br>• <a href="basic_api/sync_control/inter_core_sync/CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>/<a href="basic_api/sync_control/inter_core_sync/CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a><br>• <a href="basic_api/sync_control/inter_core_sync/SyncAll.html">SyncAll</a>（硬件同步场景）<br>软件同步：<br>• <a href="basic_api/sync_control/inter_core_sync/IBSet.html">IBSet</a>/<a href="basic_api/sync_control/inter_core_sync/IBWait.html">IBWait</a><br>• <a href="basic_api/sync_control/inter_core_sync/SyncAll.html">SyncAll</a>（软件同步场景）<br>• <a href="basic_api/sync_control/inter_core_sync/InitDetermineComputeWorkspace.html">InitDetermineComputeWorkspace</a>、<a href="basic_api/sync_control/inter_core_sync/NotifyNextBlock.html">NotifyNextBlock</a>、<a href="basic_api/sync_control/inter_core_sync/WaitPreBlock.html">WaitPreBlock</a>（三个接口需组合使用）</td></tr><tr><td>高阶API</td><td>高阶API的核间同步由具体接口场景决定：<br>• Matmul内部可能使用<a href="basic_api/sync_control/inter_core_sync/CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>/<a href="basic_api/sync_control/inter_core_sync/CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>，使用Matmul对象时需避免flagId冲突。<br>• HCCL接口的跨核依赖按其接口说明使用<a href="basic_api/sync_control/inter_core_sync/SyncAll.html">SyncAll</a>或其他核间同步接口。</td></tr></tbody></table><h2 id="通用说明">通用说明<a class="header-anchor" href="#通用说明">​</a></h2><h3 id="所需头文件和库文件">所需头文件和库文件<a id="header_and_library_requirements"></a><a class="header-anchor" href="#所需头文件和库文件">​</a></h3><p>按所用API类别包含公共头文件。若具体API另有头文件或链接要求，应遵循该接口的说明。头文件中未在API资料中公开的接口，不作为对外接口使用。</p><p><strong>表6</strong> 各类API的头文件和链接说明</p><table><thead><tr><th>API类别</th><th>常用入口头文件</th><th>说明</th></tr></thead><tbody><tr><td>C API</td><td><code>${INSTALL_DIR}/asc/include/c_api/asc_simd.h</code></td><td>除试验接口外，可通过该入口包含接口。最细粒度公共头文件见<a href="c_api/c_api.html">C API列表</a>。</td></tr><tr><td>Tensor API</td><td><code>${INSTALL_DIR}/asc/include/tensor_api/tensor.h</code></td><td>统一入口及与C API的配合方式见<a href="tensor_api/tensor_api.html">Tensor API概述</a>。</td></tr><tr><td>基础API</td><td><code>${INSTALL_DIR}/asc/include/kernel_operator.h</code></td><td>接口头文件位于<code>${INSTALL_DIR}/asc/include/basic_api</code>目录。</td></tr><tr><td>高阶API</td><td><code>${INSTALL_DIR}/asc/include/kernel_operator.h</code></td><td>接口头文件位于<code>${INSTALL_DIR}/asc/include/adv_api</code>和<code>${INSTALL_DIR}/asc/include/tiling</code>目录。<br>使用配套Host Tiling接口时，需要链接<code>libtiling_api.a</code>。</td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p><code>${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：<code>/usr/local/Ascend/cann</code>。</p></div><h3 id="数据存储位置的描述方式">数据存储位置的描述方式<a class="header-anchor" href="#数据存储位置的描述方式">​</a></h3><p>本小节按C API、Tensor API、基础API和高阶API的顺序说明各类API对数据存储位置的描述方式：</p><ul><li>C API直接通过<code>__gm__</code>、<code>__ubuf__</code>、<code>__cbuf__</code>、<code>__ca__</code>、<code>__cb__</code>和<code>__cc__</code>等地址空间限定符表达位置；</li><li>Tensor API由Tensor的<code>location</code>、Layout和搬运原子对象共同确定访问粒度；</li><li>基础API通常通过<code>LocalTensor</code>、<code>GlobalTensor</code>或Layout描述位置和范围，调用者仍须保证底层地址满足硬件要求；</li><li>高阶API通常基于基础API的Tensor和Layout描述位置和范围，具体以接口说明为准。</li></ul><h4 id="C-API：地址空间限定符">C API：地址空间限定符<a class="header-anchor" href="#C-API：地址空间限定符">​</a></h4><p>C API通常直接使用带地址空间限定符的指针表达操作数所在的存储位置。</p><p><strong>表7</strong> C API常用地址空间限定符</p><table><thead><tr><th>地址空间限定符</th><th>物理存储位置</th><th>说明</th></tr></thead><tbody><tr><td><code>__gm__</code></td><td>Global Memory</td><td>设备端的主内存，AI Core的外部存储，用于存储大规模数据，但需要优化访问模式以提升性能。</td></tr><tr><td><code>__ubuf__</code></td><td>Unified Buffer（UB）</td><td>AI Core内部存储单元，主要用于矢量计算。</td></tr><tr><td><code>__cbuf__</code></td><td>L1 Buffer</td><td>AI Core内部物理存储单元，空间相对较大，通常用于缓存矩阵计算的输入数据。矩阵计算的输入一般需要从GM搬运到L1 Buffer，然后分别搬运到L0A Buffer和L0B Buffer。</td></tr><tr><td><code>__ca__</code></td><td>L0A Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的左矩阵。</td></tr><tr><td><code>__cb__</code></td><td>L0B Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的右矩阵。</td></tr><tr><td><code>__cc__</code></td><td>L0C Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的结果。</td></tr><tr><td><code>__fbuf__</code></td><td>Fixpipe Buffer</td><td>AI Core内部物理存储单元，通常用于存储Fixpipe搬运过程中所需的量化参数等数据。</td></tr></tbody></table><h4 id="Tensor-API：location">Tensor API：location<a class="header-anchor" href="#Tensor-API：location">​</a></h4><p>如表8所示，Tensor API通过<code>location</code>枚举标记Tensor或指针的物理存储位置。</p><p><strong>表8</strong> Tensor API物理存储位置</p><table><thead><tr><th>location</th><th>物理存储位置</th><th>说明</th></tr></thead><tbody><tr><td><code>location::gm</code></td><td>Global Memory</td><td>设备端的主内存，AI Core的外部存储，用于存储大规模数据，但需要优化访问模式以提升性能。</td></tr><tr><td><code>location::ub</code></td><td>Unified Buffer（UB）</td><td>AI Core内部存储单元，主要用于矢量计算。</td></tr><tr><td><code>location::l1</code></td><td>L1 Buffer</td><td>AI Core内部物理存储单元，空间相对较大，通常用于缓存矩阵计算的输入数据。矩阵计算的输入一般需要从GM搬运到L1 Buffer，然后分别搬运到L0A Buffer和L0B Buffer。</td></tr><tr><td><code>location::l0a</code></td><td>L0A Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的左矩阵。</td></tr><tr><td><code>location::l0b</code></td><td>L0B Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的右矩阵。</td></tr><tr><td><code>location::l0c</code></td><td>L0C Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的结果。</td></tr><tr><td><code>location::bias</code></td><td>BiasTable Buffer</td><td>偏置存储，AI Core内部物理存储单元，通常用于存储矩阵计算所需的Bias（偏置）数据。</td></tr><tr><td><code>location::fixbuf</code></td><td>Fixpipe Buffer</td><td>AI Core内部物理存储单元，通常用于存储Fixpipe搬运过程中所需的量化参数等数据。</td></tr></tbody></table><h4 id="基础API和高阶API：TPosition">基础API和高阶API：TPosition<a class="header-anchor" href="#基础API和高阶API：TPosition">​</a></h4><p><code>TPosition</code>是基础API和部分高阶API使用的逻辑存储位置类型。常见取值及其物理映射见表9，同一逻辑位置在不同产品上的物理映射可能不同。</p><p><strong>表9</strong> TPosition与物理内存映射关系</p><p><a id="tposition_memory_mapping"></a></p><table><thead><tr><th>TPosition</th><th>物理存储位置</th></tr></thead><tbody><tr><td>GM</td><td>Global Memory</td></tr><tr><td>VECIN</td><td>UB</td></tr><tr><td>VECCALC</td><td>UB</td></tr><tr><td>VECOUT</td><td>UB</td></tr><tr><td>A1</td><td>L1 Buffer</td></tr><tr><td>A2</td><td>L0A Buffer</td></tr><tr><td>B1</td><td>L1 Buffer</td></tr><tr><td>B2</td><td>L0B Buffer</td></tr><tr data-filter="950"><td>C1</td><td>Ascend 950PR&amp;950DT系列产品，L1 Buffer。<br>Atlas训练系列产品，Unified Buffer（UB）。<br>Atlas推理系列产品AI Core，UB。<br>Atlas A2系列产品，L1 Buffer。<br>Atlas A3系列产品，L1 Buffer。<br>Atlas 200I/500 A2推理产品，UB。</td></tr><tr data-filter="950"><td>C2</td><td>Ascend 950PR&amp;950DT系列产品，BiasTable Buffer。<br>Atlas训练系列产品，L0C Buffer。<br>Atlas推理系列产品AI Core，L0C Buffer。<br>Atlas A2系列产品，BiasTable Buffer。<br>Atlas A3系列产品，BiasTable Buffer。<br>Atlas 200I/500 A2推理产品，BiasTable Buffer。</td></tr><tr><td>CO1</td><td>L0C Buffer</td></tr><tr data-filter="950"><td>CO2</td><td>Ascend 950PR&amp;950DT系列产品，Global Memory。<br>Atlas训练系列产品，UB。<br>Atlas推理系列产品AI Core，UB。<br>Atlas A2系列产品，Global Memory。<br>Atlas A3系列产品，Global Memory。<br>Atlas 200I/500 A2推理产品，Global Memory。</td></tr><tr><td>TSCM</td><td>L1 Buffer</td></tr><tr data-filter="950"><td>SPM</td><td>Ascend 950PR&amp;950DT系列产品，Global Memory。<br>Atlas训练系列产品，L1 Buffer。<br>Atlas推理系列产品AI Core，L1 Buffer。<br>Atlas A2系列产品，Global Memory。<br>Atlas A3系列产品，Global Memory。</td></tr><tr data-filter="950"><td>C2PIPE2GM</td><td>Ascend 950PR&amp;950DT系列产品，Fixpipe Buffer。<br>Atlas A2系列产品，Fixpipe Buffer。<br>Atlas A3系列产品，Fixpipe Buffer。</td></tr></tbody></table></article></div>',1)])])}const A=a(i,[["render",d]]);export{p as __pageData,A as default};
